export default function BrandCarousel() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isPaused, setIsPaused] = useState(false);

  useEffect(() => {
    const scroll = scrollRef.current;
    if (!scroll) return;

    let animationId: number;
    let position = 0;
    const speed = 0.5;

    const animate = () => {
      if (!isPaused) {
        position += speed;
        if (position >= scroll.scrollWidth / 2) {
          position = 0;
        }
        scroll.scrollLeft = position;
      }
      animationId = requestAnimationFrame(animate);
    };

    animationId = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [isPaused]);

  const duplicatedBrands = [...brands, ...brands];

  return (
    <section className="brand-carousel-section">
      <div className="brand-carousel-container">
        <div
          ref={scrollRef}
          className="brand-carousel-track"
          onMouseEnter={() => setIsPaused(true)}
          onMouseLeave={() => setIsPaused(false)}
        >
          {duplicatedBrands.map((brand, index) => (
            <div key={`${brand.name}-${index}`} className="brand-item">
              <img
                src={brand.logo}
                alt={brand.name}
                className="brand-logo"
              />
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

'use client';

import { useState, useMemo } from 'react';
import ProductImage from './ProductImage';
import { formatCurrency } from '@/lib/currency';

interface Product {
  id: string;
  slug: string;
  name: string;
  category: string;
  brand: string;
  price: number;
  images: string[];
  description: string;
  availability: string;
  features: string[];
  tags: string[];
}

interface CategoryProductsProps {
  products: Product[];
  categorySlug: string;
  brands: string[];
  filters: {
    search: string;
    brands: string[];
    priceRange: [number, number];
    sortBy: string;
  };
  onFilterChange: (filters: {
    search: string;
    brands: string[];
    priceRange: [number, number];
    sortBy: string;
  }) => void;
}

export default function CategoryProducts({
  products,
  categorySlug,
  brands,
  filters,
  onFilterChange,
}: CategoryProductsProps) {
  const filteredProducts = useMemo(() => {
    let filtered = [...products];

    // Search filter
    if (filters.search) {
      const searchLower = filters.search.toLowerCase();
      filtered = filtered.filter(
        (p) =>
          p.name.toLowerCase().includes(searchLower) ||
          p.brand.toLowerCase().includes(searchLower) ||
          p.description.toLowerCase().includes(searchLower)
      );
    }

    // Brand filter
    if (filters.brands.length > 0) {
      filtered = filtered.filter((p) => filters.brands.includes(p.brand));
    }

    // Price filter
    filtered = filtered.filter(
      (p) => p.price >= filters.priceRange[0] && p.price <= filters.priceRange[1]
    );

    // Sort
    switch (filters.sortBy) {
      case 'price-asc':
        filtered.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        filtered.sort((a, b) => b.price - a.price);
        break;
      case 'name-asc':
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'name-desc':
        filtered.sort((a, b) => b.name.localeCompare(a.name));
        break;
      default:
        break;
    }

    return filtered;
  }, [products, filters]);

  return (
    <>
      <div className="products-grid">
        {filteredProducts.length > 0 ? (
          filteredProducts.map((product) => (
            <div key={product.id} className="product-item">
              <div className="product-item-image">
                <ProductImage
                  src={product.images[0] || '/assets/grau-isolado.png'}
                  alt={product.name}
                />
                <span className="product-item-brand">{product.brand}</span>
              </div>
              <div className="product-item-details">
                <h3>{product.name}</h3>
                <p className="product-item-price">{formatCurrency(product.price)}</p>
                <a
                  href={`/produtos/${categorySlug}/${product.slug}`}
                  className="button"
                >
                  Ver detalhes
                </a>
              </div>
            </div>
          ))
        ) : (
          <div className="no-products">
            <p>Nenhum produto encontrado com os filtros selecionados.</p>
          </div>
        )}
      </div>

      {filteredProducts.length > 0 && (
        <div className="products-count">
          <p>Mostrando {filteredProducts.length} produto(s)</p>
        </div>
      )}
    </>
  );
}

