'use client';

import { useState, useEffect, useRef } from 'react';
import ProductImage from './ProductImage';
import { formatCurrency } from '@/lib/currency';

interface Product {
  id: string;
  slug: string;
  name: string;
  category: string;
  brand: string;
  price: number;
  images: string[];
  description: string;
  availability: string;
}

interface ProductCarouselProps {
  products: Product[];
  title?: string;
  showBrand?: boolean;
  autoPlay?: boolean;
  autoPlayInterval?: number;
}

export default function ProductCarousel({
  products,
  title,
  showBrand = true,
  autoPlay = false,
  autoPlayInterval = 5000,
}: ProductCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!autoPlay || isPaused) return;

    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % products.length);
    }, autoPlayInterval);

    return () => clearInterval(interval);
  }, [autoPlay, isPaused, autoPlayInterval, products.length]);

  const goToSlide = (index: number) => {
    setCurrentIndex(index);
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % products.length);
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + products.length) % products.length);
  };

  if (products.length === 0) {
    return null;
  }

  const currentProduct = products[currentIndex];

  return (
    <div
      className="product-carousel"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      {title && <h3 className="carousel-title">{title}</h3>}

      <div className="carousel-container" ref={containerRef}>
        <div className="carousel-track">
          {products.map((product, index) => (
            <div
              key={product.id}
              className={`carousel-slide ${index === currentIndex ? 'active' : ''}`}
              style={{
                transform: `translateX(${(index - currentIndex) * 100}%)`,
              }}
            >
              <div className="product-card">
                <div className="product-image">
                  <ProductImage
                    src={product.images[0] || '/assets/grau-isolado.png'}
                    alt={product.name}
                  />
                  {showBrand && (
                    <span className="product-brand">{product.brand}</span>
                  )}
                </div>
                <div className="product-info">
                  <h4 className="product-name">{product.name}</h4>
                  <p className="product-price">{formatCurrency(product.price)}</p>
                  <a
                    href={`/produtos/${product.category}/${product.slug}`}
                    className="product-link"
                  >
                    Ver detalhes
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        <button
          className="carousel-nav carousel-prev"
          onClick={prevSlide}
          aria-label="Produto anterior"
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>

        <button
          className="carousel-nav carousel-next"
          onClick={nextSlide}
          aria-label="Próximo produto"
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>
      </div>

      <div className="carousel-dots">
        {products.map((_, index) => (
          <button
            key={index}
            className={`carousel-dot ${index === currentIndex ? 'active' : ''}`}
            onClick={() => goToSlide(index)}
            aria-label={`Ir para produto ${index + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';

interface ProductImageProps {
  src: string;
  alt: string;
  className?: string;
  priority?: boolean;
}

export default function ProductImage({
  src,
  alt,
  className = '',
  priority = false,
}: ProductImageProps) {
  const [hasError, setHasError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const handleLoad = () => {
    setIsLoading(false);
  };

  const handleError = () => {
    setHasError(true);
    setIsLoading(false);
  };

  if (hasError) {
    return (
      <div className={`product-image-placeholder ${className}`}>
        <div className="placeholder-content">
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1"
            className="placeholder-icon"
          >
            <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7zm10 3a3 3 0 1 0 0-6 3 3 0 0 0 0 6z" />
          </svg>
          <span className="placeholder-text">Imagem não disponível</span>
        </div>
      </div>
    );
  }

  return (
    <div className={`product-image-wrapper ${className}`}>
      {isLoading && (
        <div className="product-image-skeleton">
          <div className="skeleton-shimmer" />
        </div>
      )}
      <img
        src={src}
        alt={alt}
        className={`product-image-img ${isLoading ? 'loading' : ''}`}
        onLoad={handleLoad}
        onError={handleError}
        loading={priority ? 'eager' : 'lazy'}
      />
    </div>
  );
}

